"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["78504"],{546117(n){n.exports=JSON.parse('{"id":7446,"title":"\u6587\u6848\u8BBE\u8BA1","description":"\u4F60\u7684\u4EFB\u52A1\u662F\u4E3A\u4E00\u4F4D\u60F3\u505A\u6C42\u804C\u3001\u804C\u573A\u8D5B\u9053\u81EA\u5A92\u4F53\uFF0C\u5728\u5C0F\u7EA2\u4E66\u548C\u6296\u97F3\u5206\u4EAB\u9762\u7ECF\u548C\u5B9E\u4E60\u7ECF\u5386\u7684\u4EBA\u63D0\u4F9B\u5177\u4F53\u7684\u843D\u5730\u65B9\u6848\u3002\u6B64\u4EBA\u62E5\u6709\u9762\u8BD5\u5F55\u5C4F\u548C\u804C\u573A\u7ECF\u5386\u7D20\u6750\uFF0C\u9762\u8BD5\u5F55\u5C4F\u5B58\u5728\u8FC7\u957F\u7684\u95EE\u9898\uFF0C\u9700\u8981\u89E3\u51B3\u8BE5\u95EE\u9898\uFF0C\u540C\u65F6\u8981\u5C06\u804C\u573A\u7D20\u6750\u5236\u4F5C\u6210\u52A8\u753B\u8FDB\u884C\u5C55\u793A\u3002\\n\u4EE5\u4E0B\u662F\u9762\u8BD5\u5F55\u5C4F\u7D20\u6750\uFF1A\\n<\u9762\u8BD5\u5F55\u5C4F>\\n{{INTERVIEW_RECORDINGS}}\\n</\u9762\u8BD5\u5F55\u5C4F>\\n\u4EE5\u4E0B\u662F\u804C\u573A\u7ECF\u5386\u7D20\u6750\uFF1A\\n<\u804C\u573A\u7ECF\u5386\u7D20\u6750>\\n{{WORKPLACE_EXPERIENCE_MATERIALS}}\\n</\u804C\u573A\u7ECF\u5386\u7D20\u6750>\\n\\n\u5728\u5236\u5B9A\u843D\u5730\u65B9\u6848\u65F6\uFF0C\u9700\u8981\u8003\u8651\u5C0F\u7EA2\u4E66\u548C\u6296\u97F3\u8FD9\u4E24\u4E2A\u5E73\u53F0\u7684\u4E0D\u540C\u7279\u70B9\uFF1A\\n- \u5C0F\u7EA2\u4E66\uFF1A\u7528\u6237\u7FA4\u4F53\u4EE5\u5E74\u8F7B\u5973\u6027\u5C45\u591A\uFF0C\u5185\u5BB9\u6CE8\u91CD\u5E72\u8D27\u5206\u4EAB\u3001\u4E2A\u4EBA\u7ECF\u9A8C\u3001\u56FE\u6587\u5F62\u5F0F\u548C\u6807\u7B7E\u8FD0\u7528\uFF0C\u6587\u6848\u98CE\u683C\u8F83\u4E3A\u4EB2\u5207\u3001\u6D3B\u6CFC\u3002\\n- \u6296\u97F3\uFF1A\u7528\u6237\u7FA4\u4F53\u66F4\u5E7F\u6CDB\uFF0C\u77ED\u89C6\u9891\u5F62\u5F0F\u4E3A\u4E3B\uFF0C\u5185\u5BB9\u9700\u8981\u6709\u8F83\u5F3A\u7684\u5438\u5F15\u529B\u548C\u611F\u67D3\u529B\uFF0C\u6CE8\u91CD\u89C6\u9891\u7684\u526A\u8F91\u3001\u97F3\u6548\u548C\u8282\u594F\u3002\\n\\n\u5177\u4F53\u843D\u5730\u6B65\u9AA4\u548C\u5EFA\u8BAE\u5982\u4E0B\uFF1A\\n1. \u5185\u5BB9\u7B56\u5212\uFF1A\u6839\u636E\u5E73\u53F0\u7279\u70B9\u548C\u7D20\u6750\uFF0C\u5206\u522B\u89C4\u5212\u5728\u5C0F\u7EA2\u4E66\u548C\u6296\u97F3\u4E0A\u53D1\u5E03\u7684\u5185\u5BB9\u3002\u4F8B\u5982\uFF0C\u5C0F\u7EA2\u4E66\u53EF\u4EE5\u64B0\u5199\u56FE\u6587\u7B14\u8BB0\u5206\u4EAB\u9762\u7ECF\u548C\u5B9E\u4E60\u7ECF\u5386\u7684\u8981\u70B9\uFF1B\u6296\u97F3\u53EF\u4EE5\u526A\u8F91\u9762\u8BD5\u5F55\u5C4F\u5236\u4F5C\u6210\u77ED\u89C6\u9891\uFF0C\u7A81\u51FA\u5173\u952E\u4FE1\u606F\u3002\u8981\u89E3\u51B3\u9762\u8BD5\u5F55\u5C4F\u8FC7\u957F\u7684\u95EE\u9898\uFF0C\u5E76\u5C06\u804C\u573A\u7D20\u6750\u5236\u4F5C\u6210\u52A8\u753B\u5C55\u793A\u3002\\n2. \u8D26\u53F7\u5B9A\u4F4D\uFF1A\u660E\u786E\u8D26\u53F7\u7684\u5B9A\u4F4D\u548C\u98CE\u683C\uFF0C\u786E\u5B9A\u76EE\u6807\u53D7\u4F17\uFF0C\u4F7F\u5185\u5BB9\u66F4\u5177\u9488\u5BF9\u6027\u3002\\n3. \u53D1\u5E03\u9891\u7387\uFF1A\u5236\u5B9A\u5408\u7406\u7684\u53D1\u5E03\u9891\u7387\uFF0C\u4FDD\u6301\u8D26\u53F7\u7684\u6D3B\u8DC3\u5EA6\uFF0C\u4F46\u4E5F\u4E0D\u8981\u8FC7\u4E8E\u9891\u7E41\u5BFC\u81F4\u7528\u6237\u75B2\u52B3\u3002\\n4. \u4E92\u52A8\u8FD0\u8425\uFF1A\u79EF\u6781\u56DE\u590D\u7528\u6237\u7684\u8BC4\u8BBA\u548C\u79C1\u4FE1\uFF0C\u4E0E\u7528\u6237\u5EFA\u7ACB\u826F\u597D\u7684\u4E92\u52A8\u5173\u7CFB\uFF0C\u63D0\u9AD8\u8D26\u53F7\u7684\u7C98\u6027\u3002\\n5. \u6570\u636E\u5206\u6790\uFF1A\u5B9A\u671F\u5206\u6790\u8D26\u53F7\u7684\u6570\u636E\uFF0C\u4E86\u89E3\u7528\u6237\u7684\u559C\u597D\u548C\u53CD\u9988\uFF0C\u4F18\u5316\u540E\u7EED\u7684\u5185\u5BB9\u548C\u8FD0\u8425\u7B56\u7565\u3002\\n\\n\u8BF7\u5728<\u56DE\u7B54>\u6807\u7B7E\u5185\u8F93\u51FA\u5168\u9762\u3001\u8BE6\u7EC6\u7684\u843D\u5730\u65B9\u6848\uFF0C\u65B9\u6848\u8981\u9488\u5BF9\u4E24\u4E2A\u5E73\u53F0\u5206\u522B\u7ED9\u51FA\u5177\u4F53\u7684\u64CD\u4F5C\u5EFA\u8BAE\uFF0C\u786E\u4FDD\u65B9\u6848\u5185\u5BB9\u4E30\u5BCC\u3001\u5B8C\u6574\u3002\\n<\u56DE\u7B54>\\n[\u5728\u6B64\u8F93\u51FA\u5B8C\u6574\u7684\u843D\u5730\u65B9\u6848]\\n</\u56DE\u7B54>\\n","remark":"\u6587\u6848\u8BBE\u8BA1","owner":"\u817E","upvotes":5,"downvotes":0,"upvoteDifference":5,"updatedAt":"2026-04-13T20:38:45.392Z"}')}}]);